use super::ConformanceStoreError;

pub const MAX_FINDING_CODES: usize = 16;

/// Stable categories Bridge may render without receiving a raw finding body.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ConformanceFindingCode {
    EvidenceMissing,
    EvidenceStale,
    ScopeUncovered,
    PolicyDrift,
    PolicyViolation,
    ReceiptMissing,
    HumanReviewRequired,
}

impl ConformanceFindingCode {
    pub fn from_i32(value: i32) -> Option<Self> {
        match value {
            1 => Some(Self::EvidenceMissing),
            2 => Some(Self::EvidenceStale),
            3 => Some(Self::ScopeUncovered),
            4 => Some(Self::PolicyDrift),
            5 => Some(Self::PolicyViolation),
            6 => Some(Self::ReceiptMissing),
            7 => Some(Self::HumanReviewRequired),
            _ => None,
        }
    }

    pub fn code(self) -> &'static str {
        match self {
            Self::EvidenceMissing => "evidence_missing",
            Self::EvidenceStale => "evidence_stale",
            Self::ScopeUncovered => "scope_uncovered",
            Self::PolicyDrift => "policy_drift",
            Self::PolicyViolation => "policy_violation",
            Self::ReceiptMissing => "receipt_missing",
            Self::HumanReviewRequired => "human_review_required",
        }
    }

    pub(super) fn as_i16(self) -> i16 {
        match self {
            Self::EvidenceMissing => 1,
            Self::EvidenceStale => 2,
            Self::ScopeUncovered => 3,
            Self::PolicyDrift => 4,
            Self::PolicyViolation => 5,
            Self::ReceiptMissing => 6,
            Self::HumanReviewRequired => 7,
        }
    }

    pub(super) fn from_i16(value: i16) -> Option<Self> {
        Self::from_i32(i32::from(value))
    }
}

pub(super) fn validate_finding_codes(
    codes: &[ConformanceFindingCode],
    finding_count: u32,
) -> Result<(), ConformanceStoreError> {
    if codes.len() > MAX_FINDING_CODES {
        return Err(ConformanceStoreError::TooManyFindingCodes);
    }
    if codes.len() > usize::try_from(finding_count).unwrap_or(usize::MAX) {
        return Err(ConformanceStoreError::FindingCodeCountExceedsFindingCount);
    }
    let mut seen = HashSet::new();
    if codes.iter().any(|code| !seen.insert(*code)) {
        return Err(ConformanceStoreError::DuplicateFindingCode);
    }
    Ok(())
}

